function mouse_move_71c6ea8d06e3b17d8587da4b5bf582e04dae8a1a0949a99d02cfcbe99906797c28d31e2ec3fa89d4c8e7d4f9a2aa4c6ec7261ffcc3f774df31a755137f957dc3(evt) {
    if (evt.buttons > 0) {
          var root = document.getElementById('71c6ea8d06e3b17d8587da4b5bf582e04dae8a1a0949a99d02cfcbe99906797c28d31e2ec3fa89d4c8e7d4f9a2aa4c6ec7261ffcc3f774df31a755137f957dc3');
          root.pauseAnimations();
          var new_time = 3 * evt.layerX / evt.target.getBBox().width;
          root.setCurrentTime(new_time);
    }
}
function on_click_71c6ea8d06e3b17d8587da4b5bf582e04dae8a1a0949a99d02cfcbe99906797c28d31e2ec3fa89d4c8e7d4f9a2aa4c6ec7261ffcc3f774df31a755137f957dc3(evt) {
    var root = document.getElementById('71c6ea8d06e3b17d8587da4b5bf582e04dae8a1a0949a99d02cfcbe99906797c28d31e2ec3fa89d4c8e7d4f9a2aa4c6ec7261ffcc3f774df31a755137f957dc3');
    //console.log(root);
    root.animationsPaused() ? root.unpauseAnimations() : root.pauseAnimations();
}
